fn quicksort(arr: &mut [i32]) {
    if arr.len() < 2 {
        return;
    }
    let pivot = arr[arr.len() / 2];
    let (left, right) = arr.split_at_mut(arr.len() / 2);

    for i in left {
        match i.cmp(&pivot) {
            std::cmp::Ordering::Less => {
                let j = i.cmp(&pivot);
                arr[left].swap_with_slice(&mut arr[right]);
                arr[right] = j.swap(*i);
            }
            _ => (),
        }
    }

    quicksort(left);
    quicksort(right);
}
