import time
from functools import wraps

def debounce(max_delay):
    stored_result = None

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            def inner():
                nonlocal stored_result
                stored_result = func(*args, **kwargs)
                if stored_result:
                    time.sleep(max_delay)
                    stored_result = None
            return inner

        return wrapper

    return decorator

@debounce(max_delay=1)
