#include <stdlib.h>

typedef struct ListNode {
    int value;
    struct ListNode *next;
} ListNode;

ListNode* deduplicateList(ListNode* head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }

    ListNode* current = head;
    ListNode* prev = NULL;

    while (current != NULL) {
        if (prev != NULL && prev->value == current->value) {
            ListNode* temp = current->next;
            prev->next = temp;
            free(current);
            current = prev;
        } else {
            prev = current;
            current = current->next;
        }
    }

    return head;
}
