interface ISortable<T> {
  compare(a: T, b: T): number;
}

function quicksort<T>(array: T[], comparator: ISortable<T>): T[] {
  if (array.length <= 1) return array;

  const pivot = array[Math.floor(array.length / 2)];
  const left = array.filter(item => comparator.compare(item, pivot) < 0);
  const middle = array.filter(item => comparator.compare(item, pivot) === 0);
  const right = array.filter(item => comparator.compare(item, pivot) > 0);

  return [...quicksort(left, comparator), ...middle, ...quicksort(right, comparator)];
}

