function deduplicate<T>(arr: T[]): T[] {
    if (arr.length <= 1) {
        return arr;
    }

    // Initialize a new array to store the deduplicated elements
    const deduplicated: T[] = [arr[0]];

    // Iterate over the array starting from the second element
    for (let i = 1; i < arr.length; i++) {
        // If the current element is different from the last element in the deduplicated array
        if (arr[i] !== deduplicated[deduplicated.length - 1]) {
            deduplicated.push(arr[i]);
        }
    }

    return deduplicated;
}
```

