}

function movingAverageRecursion(array: number[], windowSize: number): number {
  if (array.length < windowSize) {
    return array.length ? array[0] : 0;
  }

  const mid = Math.floor(windowSize / 2);
  const leftSum = movingAverageRecursion(array.slice(0, mid), windowSize);
  const rightSum = movingAverageRecursion(array.slice(-mid), windowSize);
  return (leftSum + rightSum) / windowSize;
